/* Node.js example: simple orchestrator with saga state persistence (pseudo) */

const sagaStore = new Map(); // Production: durable DB

async function startOrderSaga(order) {
  const sagaId = `saga-${order.id}`;
  sagaStore.set(sagaId, { state: 'STARTED', order });

  try {
    await paymentService.charge(order);
    sagaStore.set(sagaId, { state: 'PAID' });

    await inventoryService.reserve(order);
    sagaStore.set(sagaId, { state: 'INVENTORY_RESERVED' });

    await shippingService.schedule(order);
    sagaStore.set(sagaId, { state: 'SHIPPED' });

    sagaStore.set(sagaId, { state: 'COMPLETED' });
  } catch (err) {
    // Simple compensation logic: examine state and roll back accordingly
    const s = sagaStore.get(sagaId);
    if (s.state === 'INVENTORY_RESERVED') {
      await paymentService.refund(order);
      await inventoryService.release(order);
    } else if (s.state === 'PAID') {
      await paymentService.refund(order);
    }
    sagaStore.set(sagaId, { state: 'FAILED', reason: err.message });
  }
}
